     1→/**
     2→ * DUNGEON COMBAT SYSTEM
     3→ * Verbindet Dungeon-Generator + Enemy-System + Player-Combat
     4→ */
     5→
     6→(function() {
     7→    'use strict';
     8→
     9→    let currentDungeon = null;
    10→    let playerHealth = 100;
    11→    let playerMaxHealth = 100;
    12→    let playerDamage = 15;
    13→    let combatActive = false;
    14→    let lastHitNotification = 0; // Throttle hit notifications
    15→    // Auto-attack removed - manual only via SPACE
    16→
    17→    // CommandSystem Integration
    18→    let commandSystem = null;
    19→    if (typeof CommandSystem !== 'undefined') {
    20→        commandSystem = new CommandSystem();
    21→        console.log('✅ CommandSystem initialized for combat');
    22→    } else {
    23→        console.warn('⚠️ CommandSystem not available');
    24→    }
    25→
    26→    /**
    27→     * Startet Dungeon mit Gegnern
    28→     */
    29→    function startDungeonCombat(level = 1, scene, roomName = null) {
    30→        if (!window.DungeonGenerator || !window.DungeonEnemies) {
    31→            console.error('❌ DungeonGenerator or DungeonEnemies not loaded!');
    32→            return null;
    33→        }
    34→
    35→        // Auto-detect dungeon room if not specified
    36→        if (!roomName && window.currentRoom) {
    37→            roomName = window.currentRoom;
    38→        }
    39→
    40→        // Support all dungeon types
    41→        const validDungeons = [
    42→            'Kampfarena',
    43→            'Dungeon des Schattens',
    44→            'Dungeon der Explosion',
    45→            'Dungeon des Chaos'
    46→        ];
    47→
    48→        // Default to first dungeon if not valid
    49→        if (!roomName || !validDungeons.includes(roomName)) {
    50→            roomName = 'Dungeon des Schattens';
    51→        }
    52→
    53→        console.log(`🏰 Starting Dungeon Combat in "${roomName}" - Level ${level}`);
    54→
    55→        // Clear old enemies
    56→        if (window.DungeonEnemies) {
    57→            DungeonEnemies.clearAllEnemies();
    58→        }
    59→
    60→        // Generate new dungeon for the specific room
    61→        const dungeonConfig = DungeonGenerator.regenerateDungeon(roomName, level);
    62→        if (!dungeonConfig || !dungeonConfig.dungeon) {
    63→            console.error('❌ Failed to generate dungeon config');
    64→            return null;
    65→        }
    66→
    67→        currentDungeon = dungeonConfig.dungeon;
    68→        currentDungeon.level = level;
    69→
    70→        // Spawn enemies
    71→        DungeonEnemies.spawnEnemies(currentDungeon, scene);
    72→
    73→        // Reset player health
    74→        playerHealth = playerMaxHealth;
    75→        combatActive = true;
    76→
    77→        // Update UI
    78→        updateCombatUI();
    79→
    80→        // Setup event listeners
    81→        setupCombatEvents();
    82→
    83→        console.log(`✅ Dungeon Combat started! ${currentDungeon.enemies.length} enemies spawned`);
    84→        return currentDungeon;
    85→    }
    86→
    87→    /**
    88→     * Player attacks nearest enemy
    89→     */
    90→    function playerAttack(playerPosition) {
    91→        if (!combatActive || !playerPosition) return;
    92→
    93→        const enemy = DungeonEnemies.damageNearestEnemy(playerPosition, playerDamage, 5);
    94→
    95→        if (enemy) {
    96→            console.log(`⚔️ Player hit ${enemy.data.name}!`);
    97→
    98→            // Visual feedback - throttled to max 1 per 8 seconds
    99→            const now = Date.now();
   100→            if (typeof notify === 'function' && now - lastHitNotification > 8000) {
   101→                notify(`⚔️ Hit! -${playerDamage} HP`, 'success');
   102→                lastHitNotification = now;
   103→            }
   104→
   105→            // Check if all enemies dead -> WIN
   106→            checkVictoryCondition();
   107→        }
   108→        // Removed "No enemy in range" spam notification
   109→
   110→        updateCombatUI();
   111→    }
   112→
   113→    /**
   114→     * Auto-Attack toggle
   115→     */
   116→    // Auto-attack function removed - manual combat only
   117→
   118→    /**
   119→     * Enemy attacks player (called from enemy system)
   120→     */
   121→    window.onEnemyAttack = function(damage, enemyPosition) {
   122→        if (!combatActive) return;
   123→
   124→        playerHealth = Math.max(0, playerHealth - damage);
   125→        console.log(`💥 Player took ${damage} damage! HP: ${playerHealth}/${playerMaxHealth}`);
   126→
   127→        if (typeof notify === 'function') {
   128→            notify(`💥 Took ${damage} damage!`, 'error');
   129→        }
   130→
   131→        updateCombatUI();
   132→
   133→        if (playerHealth <= 0) {
   134→            gameOver();
   135→        }
   136→    };
   137→
   138→    /**
   139→     * Enemy killed (called from enemy system)
   140→     */
   141→    window.onEnemyKilled = function(xp, loot, position) {
   142→        console.log(`💀 Enemy defeated! +${xp} XP, Loot:`, loot);
   143→
   144→        if (typeof notify === 'function') {
   145→            notify(`+${xp} XP | Loot: ${loot.join(', ')}`, 'success');
   146→        }
   147→
   148→        // Add XP to player (TODO: Connect to backend)
   149→        // Update UI
   150→        updateCombatUI();
   151→
   152→        // Check victory
   153→        checkVictoryCondition();
   154→    };
   155→
   156→    /**
   157→     * Check if all enemies dead
   158→     */
   159→    function checkVictoryCondition() {
   160→        const livingEnemies = DungeonEnemies.getLivingEnemies();
   161→
   162→        if (livingEnemies.length === 0 && combatActive) {
   163→            victory();
   164→        }
   165→    }
   166→
   167→    /**
   168→     * Victory!
   169→     */
   170→    function victory() {
   171→        combatActive = false;
   172→        // Auto-attack removed
   173→
   174→        // Remove combat UI
   175→        const healthDisplay = document.getElementById('player-health-display');
   176→        if (healthDisplay) {
   177→            healthDisplay.remove();
   178→        }
   179→
   180→        console.log('🎉 VICTORY! Dungeon cleared!');
   181→
   182→        if (typeof notify === 'function') {
   183→            notify(`🎉 VICTORY! Level ${currentDungeon.level} cleared!`, 'success');
   184→        }
   185→
   186→        // Show victory UI (TODO)
   187→        showVictoryScreen();
   188→    }
   189→
   190→    /**
   191→     * Game Over
   192→     */
   193→    function gameOver() {
   194→        combatActive = false;
   195→        // Auto-attack removed
   196→
   197→        // Remove combat UI
   198→        const healthDisplay = document.getElementById('player-health-display');
   199→        if (healthDisplay) {
   200→            healthDisplay.remove();
   201→        }
   202→
   203→        console.log('💀 GAME OVER');
   204→
   205→        if (typeof notify === 'function') {
   206→            notify('💀 DEFEATED! Dungeon failed...', 'error');
   207→        }
   208→
   209→        // Clear enemies
   210→        DungeonEnemies.clearAllEnemies();
   211→
   212→        // Show game over UI (TODO)
   213→        setTimeout(() => {
   214→            if (confirm('💀 Defeated! Try again?')) {
   215→                startDungeonCombat(currentDungeon?.level || 1, window.Scene3D?.scene);
   216→            }
   217→        }, 1000);
   218→    }
   219→
   220→    /**
   221→     * Update Combat UI
   222→     */
   223→    function updateCombatUI() {
   224→        // Update health bar in header
   225→        const healthPercent = Math.floor((playerHealth / playerMaxHealth) * 100);
   226→
   227→        // Find or create health display (under chat input)
   228→        let healthDisplay = document.getElementById('player-health-display');
   229→        if (!healthDisplay) {
   230→            healthDisplay = document.createElement('div');
   231→            healthDisplay.id = 'player-health-display';
   232→            healthDisplay.style.cssText = `
   233→                position: fixed;
   234→                bottom: 70px;
   235→                left: 0;
   236→                right: 0;
   237→                background: rgba(0,0,0,0.9);
   238→                padding: 8px 20px;
   239→                color: white;
   240→                font-family: monospace;
   241→                z-index: 900;
   242→                border-top: 2px solid #667eea;
   243→                display: flex;
   244→                justify-content: space-between;
   245→                align-items: center;
   246→                font-size: 0.9rem;
   247→            `;
   248→            document.body.appendChild(healthDisplay);
   249→        }
   250→
   251→        // Color based on health
   252→        let healthColor;
   253→        if (healthPercent > 60) healthColor = '#00ff00';
   254→        else if (healthPercent > 30) healthColor = '#ffff00';
   255→        else healthColor = '#ff0000';
   256→
   257→        const enemyCount = DungeonEnemies.getLivingEnemies().length;
   258→
   259→        // CommandSystem Buttons
   260→        let commandButtons = '';
   261→        if (commandSystem) {
   262→            const commands = commandSystem.getAvailableCommands();
   263→
   264→            // Get happiness/discipline directly from DOM (Najika Status display)
   265→            const happinessEl = document.getElementById('najikaHappiness');
   266→            const disciplineEl = document.getElementById('najikaDiscipline');
   267→            const happiness = happinessEl ? parseInt(happinessEl.textContent) : 50;
   268→            const discipline = disciplineEl ? parseInt(disciplineEl.textContent) : 50;
   269→
   270→            commandButtons = `
   271→                <div style="display: flex; gap: 8px; align-items: center;">
   272→                    <span style="color: #ffcc00;">😊${happiness}</span>
   273→                    <span style="color: #cc88ff;">💪${discipline}</span>
   274→                    ${commands.commands.map(cmd => `
   275→                        <button class="cmd-btn" data-key="${cmd.key}" style="background: #667eea; color: white; border: none; padding: 6px 14px; cursor: pointer; border-radius: 4px; font-weight: bold; font-size: 0.85rem;">
   276→                            ${cmd.icon} ${cmd.label}
   277→                        </button>
   278→                    `).join('')}
   279→                    <button id="praise-btn" style="background: #00ff00; color: black; border: none; padding: 4px 10px; cursor: pointer; border-radius: 4px; font-size: 0.8rem;">👍</button>
   280→                    <button id="scold-btn" style="background: #ff0000; color: white; border: none; padding: 4px 10px; cursor: pointer; border-radius: 4px; font-size: 0.8rem;">👎</button>
   281→                    <button id="exit-combat-btn" style="background: #ff8800; color: white; border: none; padding: 4px 10px; cursor: pointer; border-radius: 4px; font-size: 0.8rem; font-weight: bold;">🚪 Beenden</button>
   282→                </div>
   283→            `;
   284→        }
   285→
   286→        healthDisplay.innerHTML = `
   287→            <div style="display: flex; justify-content: space-between; align-items: center; width: 100%;">
   288→                <div style="display: flex; gap: 15px;">
   289→                    <span style="font-weight: bold;">⚔️ COMBAT</span>
   290→                    <span style="color: ${healthColor};">HP: ${playerHealth}/${playerMaxHealth}</span>
   291→                    <span style="color: #ff8888;">Enemies: ${enemyCount}</span>
   292→                    <span style="color: #88ff88;">Lv ${currentDungeon?.level || 1}</span>
   293→                </div>
   294→                ${commandButtons}
   295→            </div>
   296→        `;
   297→
   298→        // Attach button listeners
   299→        if (commandSystem) {
   300→            // Command Buttons (1-4)
   301→            document.querySelectorAll('.cmd-btn').forEach(btn => {
   302→                btn.onclick = () => {
   303→                    const key = btn.dataset.key;
   304→                    const result = commandSystem.executeCommand(key, 'idle');
   305→
   306→                    if (result.success) {
   307→                        // Execute actual attack via battle API
   308→                        if (window.Scene3D?.character?.position) {
   309→                            playerAttack(window.Scene3D.character.position);
   310→                        }
   311→
   312→                        if (typeof notify === 'function' && result.timing) {
   313→                            notify(`${result.timing.message || 'Command executed'}`,
   314→                                   result.timing.quality === 'perfect' ? 'success' : 'info');
