   214→    class Enemy {
   215→        constructor(type, position, level = 1, scene) {
   216→            this.type = type;
   217→            this.data = ENEMY_TYPES[type];
   218→            this.level = level;
   219→            this.scene = scene;
   220→
   221→            // Stats (skaliert mit Level)
   222→            this.maxHp = Math.floor(this.data.hp * (1 + level * 0.3));
