   224→            this.damage = Math.floor(this.data.damage * (1 + level * 0.2));
   225→            this.speed = this.data.speed;
   226→            this.attackRange = this.data.attackRange;
   227→            this.xp = Math.floor(this.data.xp * (1 + level * 0.5));
   228→
   229→            // Position & Movement
   230→            this.position = new THREE.Vector3(...position);
   231→            this.rotation = Math.random() * Math.PI * 2;
   232→            this.velocity = new THREE.Vector3();
   233→            this.target = null; // Player or patrol point
   234→
   235→            // AI State
   236→            this.state = AI_STATE.IDLE;
   237→            this.stateTimer = 0;
   238→            this.patrolPoints = this.generatePatrolPoints(position);
   239→            this.currentPatrolIndex = 0;
   240→            this.attackCooldown = 0;
   241→
   242→            // 3D Objects
   243→            this.group = null;
   244→            this.model = null;
   245→            this.healthBar = null;
   246→            this.mixer = null;
   247→            this.animations = {};
   248→
   249→            // Flags
   250→            this.isDead = false;
   251→            this.isLoaded = false;
   252→        }
