   254→        async load() {
   255→            try {
   256→                // Load model via KayKitLoader
   257→                const modelPath = this.data.model;
   258→                const gltf = await this.loadGLTF('/assets/' + modelPath);
   259→
   260→                this.group = new THREE.Group();
   261→                this.model = gltf.scene.clone();
   262→                this.model.scale.setScalar(this.data.scale);
   263→
   264→                // Add subtle glow effect
   265→                this.model.traverse(child => {
   266→                    if (child.isMesh) {
   267→                        child.castShadow = true;
   268→                        child.receiveShadow = true;
   269→                        // Emissive glow für Skelette
   270→                        if (child.material) {
   271→                            child.material = child.material.clone();
   272→                            child.material.emissive = new THREE.Color(this.data.color);
   273→                            child.material.emissiveIntensity = 0.2;
   274→                        }
   275→                    }
   276→                });
   277→
   278→                this.group.add(this.model);
   279→                this.group.position.copy(this.position);
   280→                this.group.rotation.y = this.rotation;
   281→
   282→                // Health Bar
   283→                this.createHealthBar();
   284→
   285→                // Animations (wenn vorhanden)
   286→                if (gltf.animations && gltf.animations.length > 0) {
   287→                    this.mixer = new THREE.AnimationMixer(this.model);
   288→                    enemyMixers.push(this.mixer);
   289→
   290→                    gltf.animations.forEach(clip => {
   291→                        this.animations[clip.name] = this.mixer.clipAction(clip);
   292→                    });
   293→
   294→                    // Play idle animation
   295→                    if (this.animations['Idle']) {
   296→                        this.animations['Idle'].play();
   297→                    }
   298→                }
   299→
   300→                this.scene.add(this.group);
   301→                this.isLoaded = true;
   302→
   303→                console.log(`✅ Enemy loaded: ${this.data.name} (Lv ${this.level})`);
   304→            } catch (error) {
   305→                console.error('❌ Enemy load failed:', error);
   306→            }
   307→        }
