   316→        createHealthBar() {
   317→            // Simple 3D health bar above enemy
   318→            const barWidth = 2;
   319→            const barHeight = 0.2;
   320→
   321→            const barGeometry = new THREE.PlaneGeometry(barWidth, barHeight);
   322→            const barMaterial = new THREE.MeshBasicMaterial({
   323→                color: 0x00ff00,
   324→                side: THREE.DoubleSide
   325→            });
   326→
   327→            this.healthBar = new THREE.Mesh(barGeometry, barMaterial);
   328→            this.healthBar.position.y = 3; // Above model
   329→            this.healthBar.renderOrder = 999; // Always on top
   330→
   331→            this.group.add(this.healthBar);
   332→        }
   333→
   334→        updateHealthBar() {
   335→            if (!this.healthBar) return;
   336→
   337→            const healthPercent = Math.max(0, this.hp / this.maxHp);
   338→
   339→            // Color: Green -> Yellow -> Red
   340→            let color;
   341→            if (healthPercent > 0.5) {
   342→                color = new THREE.Color(0x00ff00); // Green
   343→            } else if (healthPercent > 0.2) {
   344→                color = new THREE.Color(0xffff00); // Yellow
   345→            } else {
   346→                color = new THREE.Color(0xff0000); // Red
   347→            }
   348→
   349→            this.healthBar.material.color = color;
   350→            this.healthBar.scale.x = healthPercent;
   351→        }
