   353→        generatePatrolPoints(center) {
   354→            // Generate 3-5 random patrol points around spawn
   355→            const points = [];
   356→            const count = 3 + Math.floor(Math.random() * 3);
   357→            const radius = 5;
   358→
   359→            for (let i = 0; i < count; i++) {
   360→                const angle = (i / count) * Math.PI * 2;
   361→                const x = center[0] + Math.cos(angle) * radius;
   362→                const z = center[2] + Math.sin(angle) * radius;
   363→                points.push(new THREE.Vector3(x, 0, z));
   364→            }
   365→
   366→            return points;
   367→        }
   368→
   369→        update(delta, playerPosition) {
   370→            if (this.isDead || !this.isLoaded) return;
   371→
   372→            this.stateTimer += delta;
   373→            this.attackCooldown = Math.max(0, this.attackCooldown - delta);
   374→
   375→            // Update AI based on state
   376→            switch (this.state) {
   377→                case AI_STATE.IDLE:
   378→                    this.updateIdle(delta);
   379→                    break;
   380→                case AI_STATE.PATROL:
   381→                    this.updatePatrol(delta);
   382→                    break;
   383→                case AI_STATE.CHASE:
   384→                    this.updateChase(delta, playerPosition);
   385→                    break;
   386→                case AI_STATE.ATTACK:
   387→                    this.updateAttack(delta, playerPosition);
   388→                    break;
   389→            }
   390→
   391→            // Check if player in range -> chase
   392→            if (playerPosition && this.state !== AI_STATE.ATTACK) {
   393→                const distToPlayer = this.position.distanceTo(playerPosition);
   394→                if (distToPlayer < 15) { // Aggro range
   395→                    this.state = AI_STATE.CHASE;
   396→                }
   397→            }
   398→
   399→            // Apply velocity
   400→            this.position.add(this.velocity);
   401→            this.group.position.copy(this.position);
   402→            this.group.rotation.y = this.rotation;
   403→
   404→            // Billboard health bar towards camera
   405→            if (this.healthBar && window.Scene3D && Scene3D.camera) {
   406→                this.healthBar.lookAt(Scene3D.camera.position);
   407→            }
   408→        }
   409→
   410→        updateIdle(delta) {
   411→            this.velocity.set(0, 0, 0);
   412→
   413→            // Nach 2-5 Sekunden -> Patrol
   414→            if (this.stateTimer > 2 + Math.random() * 3) {
   415→                this.state = AI_STATE.PATROL;
   416→                this.stateTimer = 0;
   417→            }
   418→        }
   419→
   420→        updatePatrol(delta) {
   421→            const target = this.patrolPoints[this.currentPatrolIndex];
   422→            const direction = target.clone().sub(this.position);
   423→            const distance = direction.length();
   424→
   425→            if (distance < 0.5) {
   426→                // Reached patrol point -> next
   427→                this.currentPatrolIndex = (this.currentPatrolIndex + 1) % this.patrolPoints.length;
   428→                this.state = AI_STATE.IDLE;
   429→                this.stateTimer = 0;
   430→            } else {
   431→                // Move towards patrol point
   432→                direction.normalize();
   433→                this.velocity.set(direction.x * this.speed * delta, 0, direction.z * this.speed * delta);
   434→                this.rotation = Math.atan2(direction.x, direction.z);
   435→            }
   436→        }
   437→
   438→        updateChase(delta, playerPosition) {
   439→            if (!playerPosition) {
   440→                this.state = AI_STATE.PATROL;
   441→                return;
   442→            }
   443→
   444→            const direction = playerPosition.clone().sub(this.position);
   445→            const distance = direction.length();
   446→
   447→            if (distance > 20) {
   448→                // Player zu weit -> zurück zu Patrol
   449→                this.state = AI_STATE.PATROL;
   450→                this.stateTimer = 0;
   451→            } else if (distance < this.attackRange) {
   452→                // In Attack Range -> Attack
   453→                this.state = AI_STATE.ATTACK;
   454→                this.stateTimer = 0;
   455→                this.velocity.set(0, 0, 0);
   456→            } else {
   457→                // Chase player
   458→                direction.normalize();
   459→                this.velocity.set(direction.x * this.speed * delta * 2, 0, direction.z * this.speed * delta * 2);
   460→                this.rotation = Math.atan2(direction.x, direction.z);
   461→            }
   462→        }
   463→
   464→        updateAttack(delta, playerPosition) {
   465→            if (!playerPosition) {
   466→                this.state = AI_STATE.CHASE;
   467→                return;
   468→            }
   469→
   470→            const distance = this.position.distanceTo(playerPosition);
   471→
   472→            if (distance > this.attackRange * 1.5) {
   473→                // Player escaped -> chase
   474→                this.state = AI_STATE.CHASE;
   475→            } else {
   476→                // Face player
   477→                const direction = playerPosition.clone().sub(this.position);
   478→                this.rotation = Math.atan2(direction.x, direction.z);
   479→
   480→                // Attack every 1-2 seconds
   481→                if (this.attackCooldown <= 0) {
   482→                    this.performAttack(playerPosition);
   483→                    this.attackCooldown = 1 + Math.random();
   484→                }
   485→            }
   486→        }
   487→
   488→        performAttack(playerPosition) {
   489→            console.log(`⚔️ ${this.data.name} attacks! Damage: ${this.damage}`);
   490→
   491→            // TODO: Damage player via API
   492→            // For now: Visual feedback
   493→            if (this.animations['Attack']) {
   494→                this.animations['Attack'].reset().play();
   495→            }
   496→
   497→            // Trigger damage event
   498→            if (typeof window.onEnemyAttack === 'function') {
   499→                window.onEnemyAttack(this.damage, this.position);
   500→            }
   501→        }
   502→
   503→        takeDamage(amount) {
   504→            if (this.isDead) return;
   505→
   506→            this.hp = Math.max(0, this.hp - amount);
   507→            this.updateHealthBar();
   508→
   509→            console.log(`💥 ${this.data.name} took ${amount} damage! HP: ${this.hp}/${this.maxHp}`);
   510→
   511→            if (this.hp <= 0) {
   512→                this.die();
   513→            } else {
   514→                // Play hurt animation
   515→                if (this.animations['Hit']) {
   516→                    this.animations['Hit'].reset().play();
