   570→    /**
   571→     * Wählt Enemy-Typ basierend auf Dungeon-Level & Schwierigkeit
   572→     */
   573→    function getEnemyTypeForLevel(level) {
   574→        const tier = Math.ceil(level / 3); // Level 1-3 = Tier 1, 4-6 = Tier 2, etc.
   575→
   576→        // Pool von Enemies nach Tier
   577→        const tierPools = {
   578→            1: ['skeleton_warrior', 'skeleton_archer', 'haunted_pumpkin'],
   579→            2: ['skeleton_mage', 'skeleton_tank', 'skeleton_axe', 'barrel_mimic', 'crate_golem'],
   580→            3: ['corrupted_knight', 'corrupted_rogue'],
   581→            4: ['corrupted_barbarian', 'dark_sorcerer']
   582→        };
   583→
   584→        const pool = tierPools[Math.min(tier, 4)] || tierPools[1];
   585→        return pool[Math.floor(Math.random() * pool.length)];
   586→    }
