   588→    /**
   589→     * Spawn enemies from dungeon data - ERWEITERT!
   590→     */
   591→    function spawnEnemies(dungeon, scene) {
   592→        if (!dungeon || !dungeon.enemies) return;
   593→
   594→        console.log(`🧟 Spawning ${dungeon.enemies.length} enemies (Level ${dungeon.level})...`);
   595→
   596→        dungeon.enemies.forEach((enemyData, index) => {
   597→            // Intelligente Enemy-Auswahl basierend auf Level
   598→            let enemyType;
   599→
   600→            if (dungeon.level <= 2) {
   601→                // Early levels: Nur Skelette & Pumpkins
   602→                const earlyPool = ['skeleton_warrior', 'skeleton_archer', 'haunted_pumpkin'];
   603→                enemyType = earlyPool[index % earlyPool.length];
   604→            } else if (dungeon.level <= 5) {
   605→                // Mid levels: Skelette + Mimics
   606→                const midPool = ['skeleton_mage', 'skeleton_tank', 'skeleton_axe', 'barrel_mimic', 'crate_golem'];
   607→                enemyType = midPool[index % midPool.length];
   608→            } else if (dungeon.level <= 8) {
   609→                // High levels: Corrupted Heroes
   610→                const highPool = ['corrupted_knight', 'corrupted_rogue', 'skeleton_mage', 'skeleton_axe'];
   611→                enemyType = highPool[index % highPool.length];
   612→            } else {
   613→                // End-game: Bosses & Elite
   614→                const bossPool = ['corrupted_barbarian', 'dark_sorcerer', 'corrupted_knight'];
   615→                enemyType = bossPool[index % bossPool.length];
   616→            }
   617→
   618→            // Fallback: Generic mapping
   619→            if (!ENEMY_TYPES[enemyType]) {
   620→                enemyType = getEnemyTypeForLevel(dungeon.level);
   621→            }
   622→
   623→            const enemy = new Enemy(enemyType, enemyData.position, enemyData.level || dungeon.level, scene);
   624→            enemy.load();
   625→            activeEnemies.push(enemy);
   626→        });
   627→    }
   628→
   629→    /**
   630→     * Update all active enemies
   631→     */
   632→    function updateEnemies(playerPosition) {
   633→        const delta = clock.getDelta();
   634→
   635→        // Update animation mixers
   636→        enemyMixers.forEach(mixer => {
   637→            mixer.update(delta);
   638→        });
   639→
   640→        // Update each enemy AI
   641→        activeEnemies.forEach(enemy => {
   642→            enemy.update(delta, playerPosition);
   643→        });
   644→    }
   645→
   646→    /**
   647→     * Clear all enemies (on room change)
   648→     */
   649→    function clearAllEnemies() {
   650→        activeEnemies.forEach(enemy => enemy.dispose());
   651→        activeEnemies = [];
   652→        enemyMixers = [];
   653→        console.log('🧹 All enemies cleared');
   654→    }
   655→
   656→    /**
   657→     * Damage nearest enemy (player attack)
   658→     */
   659→    function damageNearestEnemy(playerPosition, damage, range = 3) {
   660→        if (!playerPosition) return null;
   661→
   662→        let nearest = null;
   663→        let nearestDist = Infinity;
   664→
   665→        activeEnemies.forEach(enemy => {
   666→            if (enemy.isDead) return;
   667→            const dist = enemy.position.distanceTo(playerPosition);
   668→            if (dist < range && dist < nearestDist) {
   669→                nearest = enemy;
   670→                nearestDist = dist;
   671→            }
   672→        });
   673→
   674→        if (nearest) {
   675→            nearest.takeDamage(damage);
   676→            return nearest;
   677→        }
   678→
   679→        return null;
   680→    }
   681→
   682→    /**
   683→     * Get all living enemies
   684→     */
   685→    function getLivingEnemies() {
   686→        return activeEnemies.filter(e => !e.isDead);
   687→    }
   688→
   689→    // Public API
   690→    window.DungeonEnemies = {
   691→        spawnEnemies,
   692→        updateEnemies,
   693→        clearAllEnemies,
   694→        damageNearestEnemy,
   695→        getLivingEnemies,
   696→        Enemy,
   697→        ENEMY_TYPES,
   698→        AI_STATE
   699→    };
   700→
